92	struct proxy_header_v2 {
93	    uint8_t sig[12];
94	    uint8_t cmd_ver;
95	    uint8_t fam;
96	    uint16_t len;
97	    union {
98	        struct {
99	            in_addr_t src_addr;
100	            in_addr_t dst_addr;
101	            uint16_t src_port;
102	            uint16_t dst_port;
103	        } ip4;
104	        struct {
105	            struct in6_addr src_addr;
106	            struct in6_addr dst_addr;
107	            uint16_t src_port;
108	            uint16_t dst_port;
109	        } ip6;
110	    } addr;
111	};
