139	static char *
140	strsep_char(char *strp, char delim)
141	{
142	    char *ptr;
143	
144	    if (UNLIKELY(!strp))
145	        return NULL;
146	
147	    ptr = strchr(strp, delim);
148	    if (UNLIKELY(!ptr))
149	        return NULL;
150	
151	    *ptr = '\0';
152	    return ptr + 1;
153	}
