461	static char *
462	identify_http_path(struct lwan_request *request, char *buffer)
463	{
464	    struct lwan_request_parser_helper *helper = request->helper;
465	    static const size_t minimal_request_line_len = sizeof("/ HTTP/1.0") - 1;
466	    char *space, *end_of_line;
467	    ptrdiff_t end_len;
468	
469	    if (UNLIKELY(*buffer != '/'))
470	        return NULL;
471	
472	    end_len = buffer - helper->buffer->value;
473	    if (UNLIKELY((size_t)end_len >= helper->buffer->len))
474	        return NULL;
475	
476	    end_of_line = memchr(buffer, '\r', helper->buffer->len - (size_t)end_len);
477	    if (UNLIKELY(!end_of_line))
478	        return NULL;
479	    if (UNLIKELY((size_t)(end_of_line - buffer) < minimal_request_line_len))
480	        return NULL;
481	    *end_of_line = '\0';
482	
483	    space = end_of_line - sizeof("HTTP/X.X");
484	
485	    request->url.value = buffer;
486	    request->url.len = (size_t)(space - buffer);
487	    parse_fragment_and_query(request, space);
488	    request->original_url = request->url;
489	
490	    *space++ = '\0';
491	
492	    STRING_SWITCH_LARGE(space) {
493	    case MULTICHAR_CONSTANT_LARGE('H','T','T','P','/','1','.','0'):
494	        request->flags |= REQUEST_IS_HTTP_1_0;
495	        break;
496	    case MULTICHAR_CONSTANT_LARGE('H','T','T','P','/','1','.','1'):
497	        break;
498	    default:
499	        return NULL;
500	    }
501	
502	    return end_of_line + 1;
503	}
504	
505	#define HEADER(hdr)                                                            \
506	    ({                                                                         \
507	        if (UNLIKELY(end - sizeof(hdr) + 1 < p))                               \
508	            continue;                                                          \
509	        p += sizeof(hdr) - 1;                                                  \
510	        if (UNLIKELY(string_as_int16(p) !=                                     \
511	                     MULTICHAR_CONSTANT_SMALL(':', ' ')))                      \
512	            continue;                                                          \
513	        *end = '\0';                                                           \
514	        char *value = p + sizeof(": ") - 1;                                    \
515	        (struct lwan_value){.value = value, .len = (size_t)(end - value)};     \
516	    })
517	
518	static bool parse_headers(struct lwan_request_parser_helper *helper,
519	                          char *buffer,
520	                          char *buffer_end)
521	{
522	    char **header_start = helper->header_start;
523	    char *p;
524	    size_t n_headers = 0;
525	    bool ret = false;
526	
527	    for (p = buffer + 1; n_headers < N_HEADER_START && buffer_end > p;) {
528	        char *next_chr = p;
529	        char *next_hdr = memchr(next_chr, '\r', (size_t)(buffer_end - p));
530	
531	        if (!next_hdr)
532	            goto process;
533	
534	        if (buffer_end - next_chr == 2)
535	            goto process;
536	
537	        header_start[n_headers++] = next_chr;
538	        header_start[n_headers++] = next_hdr;
539	
540	        p = next_hdr + 2;
541	    }
542	
543	    goto out; /* Header array isn't large enough */
544	
545	process:
546	    ret = true;
547	
548	    for (size_t i = 0; i < n_headers; i += 2) {
549	        char *end = header_start[i + 1];
550	
551	        p = header_start[i];
552	
553	        STRING_SWITCH_L(p) {
554	        case MULTICHAR_CONSTANT_L('A','c','c','e'):
555	            p += sizeof("Accept") - 1;
556	
557	            STRING_SWITCH_L(p) {
558	            case MULTICHAR_CONSTANT_L('-','E','n','c'):
559	                helper->accept_encoding = HEADER("-Encoding");
560	                break;
561	            }
562	            break;
563	        case MULTICHAR_CONSTANT_L('A','u','t','h'):
564	            helper->authorization = HEADER("Authorization");
565	            break;
566	        case MULTICHAR_CONSTANT_L('C','o','n','n'):
567	            helper->connection = HEADER("Connection");
568	            break;
569	        case MULTICHAR_CONSTANT_L('C','o','n','t'):
570	            p += sizeof("Content") - 1;
571	
572	            STRING_SWITCH_L(p) {
573	            case MULTICHAR_CONSTANT_L('-','T','y','p'):
574	                helper->content_type = HEADER("-Type");
575	                break;
576	            case MULTICHAR_CONSTANT_L('-','L','e','n'):
577	                helper->content_length = HEADER("-Length");
578	                break;
579	            }
580	            break;
581	        case MULTICHAR_CONSTANT_L('C','o','o','k'):
582	            helper->cookie = HEADER("Cookie");
583	            break;
584	        case MULTICHAR_CONSTANT_L('I','f','-','M'):
585	            helper->if_modified_since.raw = HEADER("If-Modified-Since");
586	            break;
587	        case MULTICHAR_CONSTANT_L('R','a','n','g'):
588	            helper->range.raw = HEADER("Range");
589	            break;
590	        }
591	    }
592	
593	    STRING_SWITCH_SMALL(p) {
594	    case MULTICHAR_CONSTANT_SMALL('\r', '\n'):
595	        if (p[2] != '\0')
596	            helper->next_request = p + sizeof("\r\n") - 1;
597	        goto out;
598	    }
599	
600	out:
601	    helper->n_header_start = n_headers;
602	    return ret;
603	}
604	
605	#undef HEADER_RAW
606	#undef HEADER
