608	static void
609	parse_if_modified_since(struct lwan_request_parser_helper *helper)
610	{
611	    time_t parsed;
612	
613	    if (UNLIKELY(!helper->if_modified_since.raw.len))
614	        return;
615	
616	    if (UNLIKELY(lwan_parse_rfc_time(helper->if_modified_since.raw.value, &parsed) < 0))
617	        return;
618	
619	    helper->if_modified_since.parsed = parsed;
620	}
