622	static void
623	parse_range(struct lwan_request_parser_helper *helper)
624	{
625	    if (UNLIKELY(helper->range.raw.len <= (sizeof("bytes=") - 1)))
626	        return;
627	
628	    char *range = helper->range.raw.value;
629	    if (UNLIKELY(strncmp(range, "bytes=", sizeof("bytes=") - 1)))
630	        return;
631	
632	    range += sizeof("bytes=") - 1;
633	    uint64_t from, to;
634	
635	    if (sscanf(range, "%"SCNu64"-%"SCNu64, &from, &to) == 2) {
636	        if (UNLIKELY(from > OFF_MAX || to > OFF_MAX))
637	            goto invalid_range;
638	
639	        helper->range.from = (off_t)from;
640	        helper->range.to = (off_t)to;
641	    } else if (sscanf(range, "-%"SCNu64, &to) == 1) {
642	        if (UNLIKELY(to > OFF_MAX))
643	            goto invalid_range;
644	
645	        helper->range.from = 0;
646	        helper->range.to = (off_t)to;
647	    } else if (sscanf(range, "%"SCNu64"-", &from) == 1) {
648	        if (UNLIKELY(from > OFF_MAX))
649	            goto invalid_range;
650	
651	        helper->range.from = (off_t)from;
652	        helper->range.to = -1;
653	    } else {
654	invalid_range:
655	        helper->range.from = -1;
656	        helper->range.to = -1;
657	    }
658	}
