693	static ALWAYS_INLINE void parse_connection_header(struct lwan_request *request)
694	{
695	    struct lwan_request_parser_helper *helper = request->helper;
696	    bool has_keep_alive = false;
697	    bool has_close = false;
698	
699	    if (!helper->connection.len)
700	        goto out;
701	
702	    for (const char *p = helper->connection.value; *p; p++) {
703	        STRING_SWITCH_L(p) {
704	        case MULTICHAR_CONSTANT_L('k','e','e','p'):
705	        case MULTICHAR_CONSTANT_L(' ', 'k','e','e'):
706	            has_keep_alive = true;
707	            break;
708	        case MULTICHAR_CONSTANT_L('c','l','o','s'):
709	        case MULTICHAR_CONSTANT_L(' ', 'c','l','o'):
710	            has_close = true;
711	            break;
712	        case MULTICHAR_CONSTANT_L('u','p','g','r'):
713	        case MULTICHAR_CONSTANT_L(' ', 'u','p','g'):
714	            request->conn->flags |= CONN_IS_UPGRADE;
715	            break;
716	        }
717	
718	        if (!(p = strchr(p, ',')))
719	            break;
720	    }
721	
722	out:
723	    if (LIKELY(!(request->flags & REQUEST_IS_HTTP_1_0)))
724	        has_keep_alive = !has_close;
725	
726	    if (has_keep_alive)
727	        request->conn->flags |= CONN_KEEP_ALIVE;
728	    else
729	        request->conn->flags &= ~CONN_KEEP_ALIVE;
730	}
