732	#if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
733	static void save_to_corpus_for_fuzzing(const struct lwan_value *orig_buffer)
734	{
735	    struct lwan_value buffer = *orig_buffer;
736	    char corpus_name[PATH_MAX];
737	    const char *crlfcrlf;
738	    int fd;
739	
740	    if (!(crlfcrlf = memmem(buffer.value, buffer.len, "\r\n\r\n", 4)))
741	        return;
742	    buffer.len = (size_t)(crlfcrlf - buffer.value + 4);
743	
744	try_another_file_name:
745	    snprintf(corpus_name, sizeof(corpus_name), "corpus-request-%d", rand());
746	
747	    fd = open(corpus_name, O_WRONLY | O_CLOEXEC | O_CREAT | O_EXCL, 0644);
748	    if (fd < 0)
749	        goto try_another_file_name;
750	
751	    for (ssize_t total_written = 0; total_written != (ssize_t)buffer.len;) {
752	        ssize_t r = write(fd, buffer.value, buffer.len);
753	
754	        if (r < 0) {
755	            if (errno == EAGAIN || errno == EINTR)
756	                continue;
757	
758	            close(fd);
759	            unlink(corpus_name);
760	            goto try_another_file_name;
761	        }
762	
763	        total_written += r;
764	    }
765	
766	    close(fd);
767	    lwan_status_debug("Request saved to %s", corpus_name);
768	}
769	#endif
