893	static ALWAYS_INLINE enum lwan_http_status
894	read_request(struct lwan_request *request)
895	{
896	    return read_from_request_socket(request, request->helper->buffer,
897	                                    DEFAULT_BUFFER_SIZE,
898	                                    read_request_finalizer);
899	}
