901	static enum lwan_read_finalizer
902	post_data_finalizer(size_t total_read,
903	                    size_t buffer_size,
904	                    struct lwan_request_parser_helper *helper,
905	                    int n_packets)
906	{
907	    if (buffer_size == total_read)
908	        return FINALIZER_DONE;
909	
910	    /* For POST requests, the body can be larger, and due to small MTUs on
911	     * most ethernet connections, responding with a timeout solely based on
912	     * number of packets doesn't work.  Use keepalive timeout instead.  */
913	    if (UNLIKELY(time(NULL) > helper->error_when_time))
914	        return FINALIZER_ERROR_TIMEOUT;
915	
916	    /* In addition to time, also estimate the number of packets based on an
917	     * usual MTU value and the request body size.  */
918	    if (UNLIKELY(n_packets > helper->error_when_n_packets))
919	        return FINALIZER_ERROR_TIMEOUT;
920	
921	    return FINALIZER_TRY_AGAIN;
922	}
