936	static const char *is_dir(const char *v)
937	{
938	    struct stat st;
939	
940	    if (!v)
941	        return NULL;
942	
943	    if (*v != '/')
944	        return NULL;
945	
946	    if (stat(v, &st) < 0)
947	        return NULL;
948	
949	    if (!S_ISDIR(st.st_mode))
950	        return NULL;
951	
952	    if (!(st.st_mode & S_ISVTX)) {
953	        lwan_status_warning(
954	            "Using %s as temporary directory, but it doesn't have "
955	            "the sticky bit set.",
956	            v);
957	    }
958	
959	    return v;
960	}
