997	static int create_temp_file(void)
998	{
999	    char template[PATH_MAX];
1000	    mode_t prev_mask;
1001	    int ret;
1002	
1003	    if (UNLIKELY(!temp_dir))
1004	        return -ENOENT;
1005	
1006	#if defined(O_TMPFILE)
1007	    int fd = open(temp_dir,
1008	                  O_TMPFILE | O_CREAT | O_RDWR | O_EXCL | O_CLOEXEC |
1009	                      O_NOFOLLOW | O_NOATIME,
1010	                  S_IRUSR | S_IWUSR);
1011	    if (LIKELY(fd >= 0))
1012	        return fd;
1013	#endif
1014	
1015	    ret = snprintf(template, sizeof(template), "%s/lwanXXXXXX", temp_dir);
1016	    if (UNLIKELY(ret < 0 || ret >= (int)sizeof(template)))
1017	        return -EOVERFLOW;
1018	
1019	    prev_mask = umask_for_tmpfile(S_IRUSR | S_IWUSR);
1020	    ret = mkostemp(template, O_CLOEXEC);
1021	    umask_for_tmpfile(prev_mask);
1022	
1023	    if (LIKELY(ret >= 0))
1024	        unlink(template);
1025	
1026	    return ret;
1027	}
