1029	struct file_backed_buffer {
1030	    void *ptr;
1031	    size_t size;
1032	};
1033	
1034	static void
1035	free_post_buffer(void *data)
1036	{
1037	    struct file_backed_buffer *buf = data;
1038	
1039	    munmap(buf->ptr, buf->size);
1040	    free(buf);
1041	}
1042	
1043	static void*
1044	alloc_post_buffer(struct coro *coro, size_t size, bool allow_file)
1045	{
1046	    struct file_backed_buffer *buf;
1047	    void *ptr = (void *)MAP_FAILED;
1048	    int fd;
1049	
1050	    if (LIKELY(size < 1<<20)) {
1051	        ptr = coro_malloc(coro, size);
1052	
1053	        if (LIKELY(ptr))
1054	            return ptr;
1055	    }
1056	
1057	    if (UNLIKELY(!allow_file))
1058	        return NULL;
1059	
1060	    fd = create_temp_file();
1061	    if (UNLIKELY(fd < 0))
1062	        return NULL;
1063	
1064	    if (UNLIKELY(ftruncate(fd, (off_t)size) < 0)) {
1065	        close(fd);
1066	        return NULL;
1067	    }
1068	
1069	    if (MAP_HUGETLB) {
1070	        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE,
1071	                   MAP_PRIVATE | MAP_HUGETLB, fd, 0);
1072	    }
1073	    if (UNLIKELY(ptr == MAP_FAILED))
1074	        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
1075	    close(fd);
1076	    if (UNLIKELY(ptr == MAP_FAILED))
1077	        return NULL;
1078	
1079	    buf = coro_malloc_full(coro, sizeof(*buf), free_post_buffer);
1080	    if (UNLIKELY(!buf)) {
1081	        munmap(ptr, size);
1082	        return NULL;
1083	    }
1084	
1085	    buf->ptr = ptr;
1086	    buf->size = size;
1087	    return ptr;
1088	}
