1090	static enum lwan_http_status read_post_data(struct lwan_request *request)
1091	{
1092	    struct lwan_request_parser_helper *helper = request->helper;
1093	    /* Holy indirection, Batman! */
1094	    struct lwan_config *config = &request->conn->thread->lwan->config;
1095	    const size_t max_post_data_size = config->max_post_data_size;
1096	    char *new_buffer;
1097	    long parsed_size;
1098	
1099	    if (UNLIKELY(!helper->content_length.value))
1100	        return HTTP_BAD_REQUEST;
1101	    parsed_size = parse_long(helper->content_length.value, -1);
1102	    if (UNLIKELY(parsed_size < 0))
1103	        return HTTP_BAD_REQUEST;
1104	    if (UNLIKELY(parsed_size >= (long)max_post_data_size))
1105	        return HTTP_TOO_LARGE;
1106	
1107	    size_t post_data_size = (size_t)parsed_size;
1108	    size_t have;
1109	    if (!helper->next_request) {
1110	        have = 0;
1111	    } else {
1112	        char *buffer_end = helper->buffer->value + helper->buffer->len;
1113	        have = (size_t)(ptrdiff_t)(buffer_end - helper->next_request);
1114	
1115	        if (have >= post_data_size) {
1116	            helper->post_data.value = helper->next_request;
1117	            helper->post_data.len = post_data_size;
1118	            helper->next_request += post_data_size;
1119	            return HTTP_OK;
1120	        }
1121	    }
1122	
1123	    new_buffer = alloc_post_buffer(request->conn->coro, post_data_size + 1,
1124	                                   config->allow_post_temp_file);
1125	    if (UNLIKELY(!new_buffer))
1126	        return HTTP_INTERNAL_ERROR;
1127	
1128	    helper->post_data.value = new_buffer;
1129	    helper->post_data.len = post_data_size;
1130	    if (have)
1131	        new_buffer = mempcpy(new_buffer, helper->next_request, have);
1132	    helper->next_request = NULL;
1133	
1134	    helper->error_when_time = time(NULL) + config->keep_alive_timeout;
1135	    helper->error_when_n_packets = calculate_n_packets(post_data_size);
1136	
1137	    struct lwan_value buffer = {.value = new_buffer,
1138	                                .len = post_data_size - have};
1139	    return read_from_request_socket(request, &buffer, buffer.len,
1140	                                    post_data_finalizer);
1141	}
