1143	static char *
1144	parse_proxy_protocol(struct lwan_request *request, char *buffer)
1145	{
1146	    STRING_SWITCH(buffer) {
1147	    case MULTICHAR_CONSTANT('P','R','O','X'):
1148	        return parse_proxy_protocol_v1(request, buffer);
1149	    case MULTICHAR_CONSTANT('\x0D','\x0A','\x0D','\x0A'):
1150	        return parse_proxy_protocol_v2(request, buffer);
1151	    }
1152	
1153	    return buffer;
1154	}
