1156	static enum lwan_http_status
1157	parse_http_request(struct lwan_request *request)
1158	{
1159	    struct lwan_request_parser_helper *helper = request->helper;
1160	    char *buffer = helper->buffer->value;
1161	
1162	    if (request->flags & REQUEST_ALLOW_PROXY_REQS) {
1163	        /* REQUEST_ALLOW_PROXY_REQS will be cleared in lwan_process_request() */
1164	
1165	        buffer = parse_proxy_protocol(request, buffer);
1166	        if (UNLIKELY(!buffer))
1167	            return HTTP_BAD_REQUEST;
1168	    }
1169	
1170	    buffer = ignore_leading_whitespace(buffer);
1171	
1172	    char *path = identify_http_method(request, buffer);
1173	    if (UNLIKELY(!path))
1174	        return HTTP_NOT_ALLOWED;
1175	
1176	    buffer = identify_http_path(request, path);
1177	    if (UNLIKELY(!buffer))
1178	        return HTTP_BAD_REQUEST;
1179	
1180	    if (UNLIKELY(!parse_headers(helper, buffer,
1181	                                helper->buffer->value + helper->buffer->len)))
1182	        return HTTP_BAD_REQUEST;
1183	
1184	    ssize_t decoded_len = url_decode(request->url.value);
1185	    if (UNLIKELY(decoded_len < 0))
1186	        return HTTP_BAD_REQUEST;
1187	    request->original_url.len = request->url.len = (size_t)decoded_len;
1188	
1189	    parse_connection_header(request);
1190	
1191	    return HTTP_OK;
1192	}
