1194	enum lwan_http_status
1195	lwan_request_websocket_upgrade(struct lwan_request *request)
1196	{
1197	    static const unsigned char websocket_uuid[] =
1198	        "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
1199	    char header_buf[DEFAULT_HEADERS_SIZE];
1200	    size_t header_buf_len;
1201	    unsigned char digest[20];
1202	    sha1_context ctx;
1203	    char *encoded;
1204	
1205	    if (UNLIKELY(request->flags & RESPONSE_SENT_HEADERS))
1206	        return HTTP_INTERNAL_ERROR;
1207	
1208	    if (UNLIKELY(!(request->conn->flags & CONN_IS_UPGRADE)))
1209	        return HTTP_BAD_REQUEST;
1210	
1211	    const char *upgrade = lwan_request_get_header(request, "Upgrade");
1212	    if (UNLIKELY(!upgrade || !streq(upgrade, "websocket")))
1213	        return HTTP_BAD_REQUEST;
1214	
1215	    const char *sec_websocket_key =
1216	        lwan_request_get_header(request, "Sec-WebSocket-Key");
1217	    if (UNLIKELY(!sec_websocket_key))
1218	        return HTTP_BAD_REQUEST;
1219	    const size_t sec_websocket_key_len = strlen(sec_websocket_key);
1220	    if (UNLIKELY(!base64_validate((void *)sec_websocket_key, sec_websocket_key_len)))
1221	        return HTTP_BAD_REQUEST;
1222	
1223	    sha1_init(&ctx);
1224	    sha1_update(&ctx, (void *)sec_websocket_key, sec_websocket_key_len);
1225	    sha1_update(&ctx, websocket_uuid, sizeof(websocket_uuid) - 1);
1226	    sha1_finalize(&ctx, digest);
1227	
1228	    encoded = (char *)base64_encode(digest, sizeof(digest), NULL);
1229	    if (UNLIKELY(!encoded))
1230	        return HTTP_INTERNAL_ERROR;
1231	    coro_defer(request->conn->coro, free, encoded);
1232	
1233	    request->flags |= RESPONSE_NO_CONTENT_LENGTH;
1234	    header_buf_len = lwan_prepare_response_header_full(
1235	        request, HTTP_SWITCHING_PROTOCOLS, header_buf, sizeof(header_buf),
1236	        (struct lwan_key_value[]){
1237	            /* Connection: Upgrade is implicit if conn->flags & CONN_IS_UPGRADE */
1238	            {.key = "Sec-WebSocket-Accept", .value = encoded},
1239	            {.key = "Upgrade", .value = "websocket"},
1240	            {},
1241	        });
1242	    if (LIKELY(header_buf_len)) {
1243	        request->conn->flags |= (CONN_FLIP_FLAGS | CONN_IS_WEBSOCKET);
1244	
1245	        lwan_send(request, header_buf, header_buf_len, 0);
1246	
1247	        coro_yield(request->conn->coro, CONN_CORO_MAY_RESUME);
1248	
1249	        return HTTP_SWITCHING_PROTOCOLS;
1250	    }
1251	
1252	    return HTTP_INTERNAL_ERROR;
1253	}
1254	
1255	static enum lwan_http_status prepare_for_response(struct lwan_url_map *url_map,
1256	                                                  struct lwan_request *request)
1257	{
1258	    struct lwan_request_parser_helper *helper = request->helper;
1259	
1260	    request->url.value += url_map->prefix_len;
1261	    request->url.len -= url_map->prefix_len;
1262	
1263	    if (url_map->flags & HANDLER_MUST_AUTHORIZE) {
1264	        if (!lwan_http_authorize(request, &helper->authorization,
1265	                                 url_map->authorization.realm,
1266	                                 url_map->authorization.password_file))
1267	            return HTTP_NOT_AUTHORIZED;
1268	    }
1269	
1270	    if (url_map->flags & HANDLER_REMOVE_LEADING_SLASH) {
1271	        while (*request->url.value == '/' && request->url.len > 0) {
1272	            ++request->url.value;
1273	            --request->url.len;
1274	        }
1275	    }
1276	
1277	    if (url_map->flags & HANDLER_PARSE_ACCEPT_ENCODING)
1278	        parse_accept_encoding(request);
1279	
1280	    if (lwan_request_get_method(request) == REQUEST_METHOD_POST) {
1281	        enum lwan_http_status status;
1282	
1283	        if (!(url_map->flags & HANDLER_HAS_POST_DATA)) {
1284	            /* FIXME: Discard POST data here? If a POST request is sent
1285	             * to a handler that is not supposed to handle a POST request,
1286	             * the next request in the pipeline will fail because the
1287	             * body of the previous request will be used as the next
1288	             * request itself. */
1289	            return HTTP_NOT_ALLOWED;
1290	        }
1291	
1292	        status = read_post_data(request);
1293	        if (UNLIKELY(status != HTTP_OK))
1294	            return status;
1295	    }
1296	
1297	    return HTTP_OK;
1298	}
1299	
1300	static bool handle_rewrite(struct lwan_request *request)
1301	{
1302	    struct lwan_request_parser_helper *helper = request->helper;
1303	
1304	    request->flags &= ~RESPONSE_URL_REWRITTEN;
1305	
1306	    parse_fragment_and_query(request, request->url.value + request->url.len);
1307	
1308	    helper->urls_rewritten++;
1309	    if (UNLIKELY(helper->urls_rewritten > 4)) {
1310	        lwan_default_response(request, HTTP_INTERNAL_ERROR);
1311	        return false;
1312	    }
1313	
1314	    return true;
1315	}
1316	
1317	char *lwan_process_request(struct lwan *l,
1318	                           struct lwan_request *request,
1319	                           struct lwan_value *buffer,
1320	                           char *next_request)
1321	{
1322	    char *header_start[N_HEADER_START];
1323	    struct lwan_request_parser_helper helper = {
1324	        .buffer = buffer,
1325	        .next_request = next_request,
1326	        .error_when_n_packets = calculate_n_packets(DEFAULT_BUFFER_SIZE),
1327	        .header_start = header_start,
1328	    };
1329	    enum lwan_http_status status;
1330	    struct lwan_url_map *url_map;
1331	
1332	    request->helper = &helper;
1333	
1334	    status = read_request(request);
1335	    if (UNLIKELY(status != HTTP_OK)) {
1336	        /* This request was bad, but maybe there's a good one in the
1337	         * pipeline.  */
1338	        if (status == HTTP_BAD_REQUEST && helper.next_request)
1339	            goto out;
1340	
1341	        /* Response here can be: HTTP_TOO_LARGE, HTTP_BAD_REQUEST (without
1342	         * next request), or HTTP_TIMEOUT.  Nothing to do, just abort the
1343	         * coroutine.  */
1344	        lwan_default_response(request, status);
1345	        coro_yield(request->conn->coro, CONN_CORO_ABORT);
1346	        __builtin_unreachable();
1347	    }
1348	
1349	    status = parse_http_request(request);
1350	    if (UNLIKELY(status != HTTP_OK)) {
1351	        lwan_default_response(request, status);
1352	        goto out;
1353	    }
1354	
1355	lookup_again:
1356	    url_map = lwan_trie_lookup_prefix(&l->url_map_trie, request->url.value);
1357	    if (UNLIKELY(!url_map)) {
1358	        lwan_default_response(request, HTTP_NOT_FOUND);
1359	        goto out;
1360	    }
1361	
1362	    status = prepare_for_response(url_map, request);
1363	    if (UNLIKELY(status != HTTP_OK)) {
1364	        lwan_default_response(request, status);
1365	        goto out;
1366	    }
1367	
1368	    status = url_map->handler(request, &request->response, url_map->data);
1369	    if (UNLIKELY(url_map->flags & HANDLER_CAN_REWRITE_URL)) {
1370	        if (request->flags & RESPONSE_URL_REWRITTEN) {
1371	            if (LIKELY(handle_rewrite(request)))
1372	                goto lookup_again;
1373	            goto out;
1374	        }
1375	    }
1376	
1377	    lwan_response(request, status);
1378	
1379	out:
1380	    return helper.next_request;
1381	}
