1383	static inline void *
1384	value_lookup(const struct lwan_key_value_array *array, const char *key)
1385	{
1386	    const struct lwan_array *la = (const struct lwan_array *)array;
1387	
1388	    if (LIKELY(la->elements)) {
1389	        struct lwan_key_value k = { .key = (char *)key };
1390	        struct lwan_key_value *entry;
1391	
1392	        entry = bsearch(&k, la->base, la->elements, sizeof(k), key_value_compare);
1393	        if (LIKELY(entry))
1394	            return entry->value;
1395	    }
1396	
1397	    return NULL;
1398	}
