1433	const char *lwan_request_get_header(struct lwan_request *request,
1434	                                    const char *header)
1435	{
1436	    char name[64];
1437	    int r;
1438	
1439	    r = snprintf(name, sizeof(name), "%s: ", header);
1440	    if (UNLIKELY(r < 0 || r >= (int)sizeof(name)))
1441	        return NULL;
1442	
1443	    for (size_t i = 0; i < request->helper->n_header_start; i += 2) {
1444	        const char *start = request->helper->header_start[i];
1445	        char *end = request->helper->header_start[i + 1];
1446	
1447	        if (UNLIKELY(end - start < r))
1448	            continue;
1449	
1450	        if (!strncasecmp(start, name, (size_t)r)) {
1451	            *end = '\0';
1452	            return start + r;
1453	        }
1454	    }
1455	
1456	    return NULL;
1457	}
1458	
1459	ALWAYS_INLINE int
1460	lwan_connection_get_fd(const struct lwan *lwan, const struct lwan_connection *conn)
1461	{
