1463	}
1464	
1465	const char *
1466	lwan_request_get_remote_address(struct lwan_request *request,
1467	            char buffer[static INET6_ADDRSTRLEN])
1468	{
1469	    struct sockaddr_storage non_proxied_addr = { .ss_family = AF_UNSPEC };
1470	    struct sockaddr_storage *sock_addr;
1471	
1472	    if (request->flags & REQUEST_PROXIED) {
1473	        sock_addr = (struct sockaddr_storage *)&request->proxy->from;
1474	
1475	        if (UNLIKELY(sock_addr->ss_family == AF_UNSPEC))
1476	            return memcpy(buffer, "*unspecified*", sizeof("*unspecified*"));
1477	    } else {
1478	        socklen_t sock_len = sizeof(non_proxied_addr);
1479	
1480	        sock_addr = &non_proxied_addr;
1481	
1482	        if (UNLIKELY(getpeername(request->fd,
1483	                                 (struct sockaddr *) sock_addr,
1484	                                 &sock_len) < 0))
1485	            return NULL;
1486	    }
1487	
1488	    if (sock_addr->ss_family == AF_INET)
1489	        return inet_ntop(AF_INET,
1490	                         &((struct sockaddr_in *) sock_addr)->sin_addr,
1491	                         buffer, INET6_ADDRSTRLEN);
1492	
1493	    return inet_ntop(AF_INET6,
1494	                     &((struct sockaddr_in6 *) sock_addr)->sin6_addr,
1495	                     buffer, INET6_ADDRSTRLEN);
1496	}
1497	
1498	static void remove_sleep(void *data1, void *data2)
1499	{
1500	    struct timeouts *wheel = data1;
1501	    struct timeout *timeout = data2;
1502	    struct lwan_request *request =
1503	        container_of(timeout, struct lwan_request, timeout);
1504	
1505	    if (request->conn->flags & CONN_SUSPENDED_BY_TIMER)
1506	        timeouts_del(wheel, timeout);
1507	}
1508	
1509	void lwan_request_sleep(struct lwan_request *request, uint64_t ms)
1510	{
1511	    struct lwan_connection *conn = request->conn;
1512	    struct timeouts *wheel = conn->thread->wheel;
1513	
1514	    assert(!(conn->flags & CONN_SUSPENDED_BY_TIMER));
1515	    conn->flags |= CONN_SUSPENDED_BY_TIMER;
1516	
1517	    request->timeout = (struct timeout) {};
1518	    timeouts_add(wheel, &request->timeout, ms);
1519	    coro_defer2(conn->coro, remove_sleep, wheel, &request->timeout);
1520	    coro_yield(conn->coro, CONN_CORO_MAY_RESUME);
1521	
1522	    assert(!(conn->flags & CONN_SUSPENDED_BY_TIMER));
1523	    assert(!(conn->flags & CONN_RESUMED_FROM_TIMER));
1524	}
