1608	#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
1609	static int useless_coro_for_fuzzing(struct coro *c __attribute__((unused)),
1610	                                    void *data __attribute__((unused)))
1611	{
1612	    return 0;
1613	}
1614	
1615	__attribute__((used)) int fuzz_parse_http_request(const uint8_t *data,
1616	                                                  size_t length)
1617	{
1618	    static struct coro_switcher switcher;
1619	    static struct coro *coro;
1620	    static char *header_start[N_HEADER_START];
1621	    static char data_copy[32767] = {0};
1622	
1623	    if (length > sizeof(data_copy))
1624	        length = sizeof(data_copy);
1625	    memcpy(data_copy, data, length);
1626	
1627	    if (!coro)
1628	        coro = coro_new(&switcher, useless_coro_for_fuzzing, NULL);
1629	
1630	    struct lwan_request_parser_helper helper = {
1631	        .buffer = &(struct lwan_value){.value = data_copy, .len = length},
1632	        .header_start = header_start,
1633	        .error_when_n_packets = 2,
1634	    };
1635	    struct lwan_connection conn = {.coro = coro};
1636	    struct lwan_request request = {.helper = &helper, .conn = &conn};
1637	
1638	    /* If the finalizer isn't happy with a request, there's no point in
1639	     * going any further with parsing it. */
1640	    if (read_request_finalizer(length, sizeof(data_copy), &helper, 1) !=
1641	        FINALIZER_DONE)
1642	        return 0;
1643	
1644	    if (parse_http_request(&request) == HTTP_OK) {
1645	        size_t gen = coro_deferred_get_generation(coro);
1646	
1647	        /* Only pointers were set in helper struct; actually parse them here. */
1648	        parse_post_data(&request);
1649	        parse_query_string(&request);
1650	        parse_cookies(&request);
1651	        parse_accept_encoding(&request);
1652	        parse_if_modified_since(&helper);
1653	        parse_range(&helper);
1654	
1655	        coro_deferred_run(coro, gen);
1656	    }
1657	
1658	    return 0;
1659	}
1660	#endif
